#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

typedef struct {
    char filename[256];
    pthread_mutex_t lock;
    int processed;
    int result; // e.g., line count or checksum
} FileJob;

typedef struct {
    FileJob *jobs;
    int count;
    int capacity;
    int next_index; // for work distribution
    pthread_mutex_t queue_lock;
    pthread_cond_t work_available;
    pthread_cond_t work_done;
    int active_workers;
    int shutdown;
} JobQueue;

void process_file(FileJob *job) {
    // Simulate processing: read file and count lines
    FILE *f = fopen(job->filename, "r");
    if (!f) return;
    int lines = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), f)) {
        lines++;
    }
    fclose(f);
    job->result = lines;
    job->processed = 1;
}

void* worker_thread(void *arg) {
    JobQueue *queue = (JobQueue*)arg;

    while (1) {
        pthread_mutex_lock(&queue->queue_lock);

        while (queue->next_index >= queue->count && !queue->shutdown) {
            pthread_cond_wait(&queue->work_available, &queue->queue_lock);
        }

        if (queue->shutdown && queue->next_index >= queue->count) {
            pthread_mutex_unlock(&queue->queue_lock);
            break;
        }

        int idx = queue->next_index++;
        FileJob *job = &queue->jobs[idx];
        queue->active_workers++;

        pthread_mutex_unlock(&queue->queue_lock);

        // Lock the specific file to ensure only one thread processes it at a time
        pthread_mutex_lock(&job->lock);

        // Process the file
        process_file(job);

        pthread_mutex_unlock(&job->lock);

        pthread_mutex_lock(&queue->queue_lock);
        queue->active_workers--;
        if (queue->next_index >= queue->count && queue->active_workers == 0) {
            pthread_cond_broadcast(&queue->work_done);
        }
        pthread_mutex_unlock(&queue->queue_lock);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <directory> <num_threads>\n", argv[0]);
        return 1;
    }

    const char *dir_path = argv[1];
    int num_threads = atoi(argv[2]);

    // Initialize job queue
    JobQueue queue;
    queue.capacity = 1024;
    queue.jobs = malloc(sizeof(FileJob) * queue.capacity);
    queue.count = 0;
    queue.next_index = 0;
    queue.active_workers = 0;
    queue.shutdown = 0;
    pthread_mutex_init(&queue.queue_lock, NULL);
    pthread_cond_init(&queue.work_available, NULL);
    pthread_cond_init(&queue.work_done, NULL);

    // Scan directory
    DIR *dir = opendir(dir_path);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_name[0] == '.') continue; // skip hidden files

        char fullpath[512];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dir_path, entry->d_name);

        struct stat st;
        if (stat(fullpath, &st) == 0 && S_ISREG(st.st_mode)) {
            if (queue.count < queue.capacity) {
                strncpy(queue.jobs[queue.count].filename, fullpath, 255);
                queue.jobs[queue.count].filename[255] = '\0';
                pthread_mutex_init(&queue.jobs[queue.count].lock, NULL);
                queue.jobs[queue.count].processed = 0;
                queue.jobs[queue.count].result = 0;
                queue.count++;
            }
        }
    }
    closedir(dir);

    // Create worker threads
    pthread_t *threads = malloc(sizeof(pthread_t) * num_threads);
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &queue);
    }

    // Wait for all work to be done
    pthread_mutex_lock(&queue.queue_lock);
    while (!(queue.next_index >= queue.count && queue.active_workers == 0)) {
        pthread_cond_wait(&queue.work_done, &queue.queue_lock);
    }
    queue.shutdown = 1;
    pthread_cond_broadcast(&queue.work_available);
    pthread_mutex_unlock(&queue.queue_lock);

    // Join threads
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print results
    for (int i = 0; i < queue.count; i++) {
        printf("File: %s, Lines: %d\n", queue.jobs[i].filename, queue.jobs[i].result);
        pthread_mutex_destroy(&queue.jobs[i].lock);
    }

    // Cleanup
    free(threads);
    free(queue.jobs);
    pthread_mutex_destroy(&queue.queue_lock);
    pthread_cond_destroy(&queue.work_available);
    pthread_cond_destroy(&queue.work_done);

    return 0;
}
